<?php
// Included only after the details controller has authorized access to $ticket.
$proposals=ticketProposals((int)$user['id'],(int)$ticket['id']);
$isOwner=(int)$ticket['usuario_id']===(int)$user['id'];
$isProvider=$user['tipo_usuario']==='prestador';
$isAssigned=$isProvider && (int)$ticket['prestador_id']===(int)$user['id'];
?>
<section class="panel-card profile-section"><h2>Propostas e atendimento</h2>
<?php if(!$proposals): ?><p>Ainda não há propostas para este chamado.</p><?php endif; ?>
<?php foreach($proposals as $proposal): ?><article class="proposal-card"><div class="panel-title-row"><h3><?= sanitize($proposal['prestador_nome']) ?></h3><a class="button button-secondary" href="<?= getBasePath() ?>pages/perfil.php?id=<?= (int)$proposal['prestador_id'] ?>">Perfil</a></div><p><?= nl2br(sanitize($proposal['resposta'])) ?></p><dl class="detail-list"><div><dt>Taxa de visita</dt><dd><?= $proposal['taxa_visita']!==null?'R$ '.number_format((float)$proposal['taxa_visita'],2,',','.'):'Não informada' ?></dd></div><div><dt>Visita agendada</dt><dd><?= $proposal['visita_em']?sanitize(date('d/m/Y H:i',strtotime($proposal['visita_em']))):'A combinar' ?></dd></div><?php if($proposal['orcamento_valor']!==null): ?><div><dt>Orçamento</dt><dd>R$ <?= number_format((float)$proposal['orcamento_valor'],2,',','.') ?> · <?= sanitize($proposal['orcamento_status']) ?><p><?= nl2br(sanitize($proposal['orcamento_descricao'])) ?></p></dd></div><?php endif; ?></dl>
<?php if($isOwner && $ticket['status']==='aberto'): ?><form method="post"><?= csrfField() ?><input type="hidden" name="prestador_id" value="<?= (int)$proposal['prestador_id'] ?>"><button class="button button-primary" name="service_action" value="selecionar">Selecionar prestador</button></form><?php endif; ?>
<?php if($isOwner && $ticket['status']==='andamento' && (int)$proposal['prestador_id']===(int)$ticket['prestador_id'] && $proposal['orcamento_valor'] && $proposal['orcamento_status']==='pendente'): ?><form method="post" class="action-row"><?= csrfField() ?><button class="button button-primary" name="service_action" value="aceitar_orcamento">Aceitar orçamento</button><button class="button button-secondary" name="service_action" value="recusar_orcamento">Recusar orçamento</button></form><?php endif; ?></article><?php endforeach; ?>
<?php if($isProvider && (($ticket['status']==='aberto' && !$ticket['prestador_id']) || ($ticket['status']==='andamento' && $isAssigned))): ?><form method="post" class="profile-section"><?= csrfField() ?><label>Sua resposta / proposta<textarea name="resposta" rows="3" maxlength="4000" required></textarea></label><button class="button button-primary" name="service_action" value="responder">Enviar resposta</button></form><?php if($ticket['status']==='aberto'): ?><form method="post" class="profile-section"><?= csrfField() ?><button class="button button-secondary" name="service_action" value="assumir">Assumir atendimento</button></form><?php endif; endif; ?>
<?php if($isAssigned && $ticket['status']==='andamento'): ?><div class="panel-grid profile-section"><form method="post"><?= csrfField() ?><h3>Visita</h3><label>Data e horário<input type="datetime-local" name="visita_em" required></label><button class="button button-secondary" name="service_action" value="visita">Marcar visita</button></form><form method="post"><?= csrfField() ?><h3>Taxa de visita</h3><label>Valor em reais<input type="number" name="valor" step="0.01" min="0" max="9999999" required></label><button class="button button-secondary" name="service_action" value="taxa">Informar taxa</button></form></div><form method="post" class="profile-section"><?= csrfField() ?><h3>Orçamento</h3><label>Valor total em reais<input type="number" name="valor" step="0.01" min="0.01" max="9999999" required></label><label>Descrição dos serviços<textarea name="descricao" maxlength="4000" required></textarea></label><button class="button button-primary" name="service_action" value="orcamento">Enviar orçamento</button></form><form method="post" data-confirm="Confirmar que o serviço foi concluído?" class="profile-section"><?= csrfField() ?><button class="button button-secondary" name="service_action" value="concluir">Finalizar serviço</button></form><?php endif; ?>
<?php if(($isOwner || managesCondominio((int)$user['id'],(int)$ticket['condominio_id'])) && in_array($ticket['status'],['aberto','andamento'],true)): ?><form method="post" data-confirm="Cancelar este chamado?" class="profile-section"><?= csrfField() ?><button class="button button-secondary" name="service_action" value="cancelar">Cancelar chamado</button></form><?php endif; ?>
</section>
